}

/* ---------- tractor beam / capture / dual fighter ---------- */
function capturePlayer(b){
  player.cap={boss:b,t:0,x0:player.x,y0:player.y};
  sCapture();
}
function finishCapture(b){
  player.cap=null;player.alive=false;
  const c={state:'held',x:b.x,y:b.y-15,fireT:60};
  b.captive=c;G.captive=c;
  loseShip();
}
function updateCaptivePull(){
  const c=player.cap;c.t++;
  const k=Math.min(1,c.t/50);
  player.x=lerp(c.x0,c.boss.x,k);player.y=lerp(c.y0,c.boss.y-14,k);
  if(c.t%6===0)sBeamPulse();
  if(k>=1)finishCapture(c.boss);
}
function updateFreeCaptive(){
  const c=G.freeCaptive;if(!c)return;
  if(player.alive&&G.respawnT===0){
    c.x+=clamp(player.x-c.x,-2,2);c.y+=1.8;
    if(c.y>=player.y-12){player.dual=true;G.freeCaptive=null;sDock();}
