}
function killPlayer(side){
  if(!player.alive||player.cap||player.inv>0||G.readyT>0||G.overT>0)return;
  if(player.dual&&side==='L'){player.dual=false;player.inv=50;spawnExpl(player.x-7,player.y,playerCols,false);sPlayerDie();return;}
  if(player.dual&&side==='R'){player.dual=false;player.inv=50;spawnExpl(player.x+7,player.y,playerCols,false);sPlayerDie();return;}
  player.alive=false;spawnExpl(player.x,player.y,playerCols,true);sPlayerDie();loseShip();
}
function updatePlayer(){
  if(player.cap){updateCaptivePull();return;}
  if(!player.alive)return;
  if(player.inv>0)player.inv--;
  const sp=2;
  if(keys.ArrowLeft||keys.a||keys.A)player.x-=sp;
  if(keys.ArrowRight||keys.d||keys.D)player.x+=sp;
  player.x=clamp(player.x,player.dual?18:10,W-(player.dual?18:10));
  if(G.fireCd>0)G.fireCd--;
  if(keys[' ']&&G.readyT===0&&shots.length<2&&G.fireCd<=0){ // max two shots on screen
    G.fireCd=12;stats.shots++;sShoot();
    if(player.dual){shots.push({x:player.x-7,y:player.y-8});shots.push({x:player.x+7,y:player.y-8});}
