}

/* ---------- collisions (hitboxes <= sprites) ---------- */
function hitBox(b,e){const s=BOX[e.type];
  return Math.abs(b.x-e.x)<=s.w/2+1&&Math.abs(b.y-e.y)<=s.h/2+3;}
function hitPlayerAt(px,py){
  if(!player.alive||player.cap||player.inv>0||G.readyT>0||G.overT>0)return null;
  if(Math.abs(py-player.y)>6)return null;
  if(player.dual){
    if(Math.abs(px-(player.x-7))<=5)return 'L';
    if(Math.abs(px-(player.x+7))<=5)return 'R';
    return null;}
  return Math.abs(px-player.x)<=4?'C':null;
}
function damageEnemy(e,x,y,instakill){
  if(e.dead)return;
  if(e.type==='boss'&&!instakill&&e.hp>1){e.hp=1;e.hit=true;sBossHit();return;}
  e.dead=true;stats.hits++;addScore(ePoints(e));
  spawnExpl(x,y,enemyCols,false);sEnemyDie();
  if(e.captive){ // boss destroyed while holding a fighter
    const c=e.captive;e.captive=null;G.captive=null;
    const diving=e.state==='diving'||e.state==='beam'||e.state==='beamApproach';
    if(diving){c.state='freed';G.freeCaptive=c;}
