}
function collide(){
  for(const b of shots)for(const e of enemies){
    if(e.state==='chal'&&e.t<0)continue;
    if(!b.dead&&!e.dead&&hitBox(b,e)){b.dead=true;damageEnemy(e,b.x,b.y,false);break;}
  }
  if(player.alive&&!player.cap){
    for(const b of ebullets){
      const s=hitPlayerAt(b.x,b.y);
      if(s){b.dead=true;killPlayer(s);}
    }
    if(G.readyT===0&&G.respawnT===0)for(const e of enemies){
      if(e.dead||e.state==='freed')continue;
      if(e.state==='chal'&&e.t<0)continue;
      if(Math.abs(e.x-player.x)<=BOX[e.type].w/2+3&&Math.abs(e.y-player.y)<=BOX[e.type].h/2+5){
        damageEnemy(e,e.x,e.y,true); // ramming destroys the enemy too
        killPlayer(e.x<player.x?'C':'C');
      }
    }
  }
  enemies=enemies.filter(e=>!e.dead);
}

/* ---------- challenging stage ---------- */
function updateChal(){
  const C=G.chal;C.t++;
  updatePlayer();updateShots();
  if(C.alive<=0&&C.t>100){
    C.wave++;
    if(C.wave>4){finishChal();return;}
    C.alive=8;C.waveHits[C.wave]=0;C.t=0;
    for(let i=0;i<8;i++)enemies.push({type:'zako',state:'chal',t:-i*10,x:0,y:-20,
      ft:i*4,frame:0,ph:R(0,6.28),x0:72+i*10,wave:C.wave,hp:1,hit:false,fireT:1e9});
  }
  for(const e of enemies){
    if(e.state==='chal'&&e.t>=0){
      e.t++;
      e.x=e.x0+46*Math.sin(e.t*0.045+e.ph)+22*Math.sin(e.t*0.1);
      e.y=-16+e.t*1.25+16*Math.sin(e.t*0.045+e.ph);
      if(e.y>H+12||e.x<-24||e.x>W+24){e.dead=true;if(e.wave===C.wave)C.alive--;}
    }else if(e.state==='chal')e.t++;
  }
  for(const b of shots)for(const e of enemies){
    if(!b.dead&&!e.dead&&e.state==='chal'&&e.t>=0&&hitBox(b,e)){
      b.dead=true;e.dead=true;C.hits++;C.waveHits[e.wave]++;stats.hits++;
      addScore(100);sChalHit();spawnExpl(e.x,e.y,enemyCols,false);
      if(e.wave===C.wave)C.alive--;
    }
  }
  shots=shots.filter(b=>!b.dead);
  enemies=enemies.filter(e=>!e.dead);
  updateExpls();
}
function finishChal(){
  const C=G.chal;let bonus=0;
  if(C.hits>=40)bonus=10000;
  else for(let w=0;w<5;w++)if(C.waveHits[w]===8)bonus+=1000;
  G.chalBonus=bonus;addScore(bonus);
  G.resT=300;G.state='chalResult';
}

/* ---------- main update ---------- */
function updatePlay(){
  if(G.readyT>0)G.readyT--;
  if(G.respawnT>0){G.respawnT--;
    if(G.respawnT===0){player.alive=true;player.x=112;player.inv=60;G.readyT=60;}}
  if(G.overT>0){ // waiting for the game-over card
    G.overT--;
    if(!G.overT){G.state='gameover';G.overT=170;}
    updateShots();updateEBullets();updateExpls();
    return;
  }
  G.stageFrames++;
  updatePlayer();
  updateShots();
  spawnGroups();
  updateEnemies();
  updateFreeCaptive();
  updateDiveScheduler();
  updateEBullets();
  collide();
  updateExpls();
  fmtUpdate();
  if(groupsDone()&&enemies.length===0&&!G.freeCaptive){G.stage++;setupStage();}
}
function update(){
  G.frame++;
  updateStars();
  switch(G.state){
    case 'title':break;
    case 'intro':if(--G.introT<=0)beginStage();break;
    case 'play':updatePlay();break;
    case 'challenging':updateChal();break;
    case 'chalResult':if(--G.resT<=0){G.stage++;setupStage();}break;
    case 'gameover':if(--G.overT<=0){G.state='results';G.resT=600;}break;
    case 'results':if(--G.resT<=0)G.state='title';break;
